## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/facetJointLogic.ts`

```typescript
export type SpineRegion = "lumbar" | "cervical" | "thoracic";
export type ProcedureType = "facet-injection" | "medial-branch-block" | "rfa-diagnostic";

export type FacetJointInput = {
  age: string; spineRegion: string; procedureType: string;
  symptomDurationMonths: string; painScore: string; symptoms: string[];
  conservativeTherapyMonths: string; conservativeTherapies: string[];
  priorFacetResponse: string; priorFacetCount: string;
  activeInfection: boolean; coagulopathy: boolean; allergy: boolean;
  diagnosticBlockPositive: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessFacetJoint(input: FacetJointInput) {
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;
  const painScore = parseFloat(input.painScore) || 0;
  const priorCount = parseInt(input.priorFacetCount) || 0;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active infection — absolute contraindication");
  if (input.coagulopathy) contraindications.push("Uncorrected coagulopathy — hold anticoagulation per guidelines");
  if (input.allergy) contraindications.push("Allergy to steroids or contrast");

  if (contraindications.length > 0) {
    return { recommendation: "Facet Injection Contraindicated", cor: "III" as COR, loe: "C", urgency: "Contraindicated", rationale: ["Contraindications identified."], contraindications, optimizationSteps: [] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  const hasAxialPain = input.symptoms.includes("axial-pain");
  const hasPainExtension = input.symptoms.includes("pain-extension");
  const hasNoNeurologic = input.symptoms.includes("no-neurologic");

  if (priorCount >= 3) {
    cor = "IIb"; urgency = "Frequency Limit Reached";
    rationale.push("Most payers limit facet injections to 3 per region per year");
    optimizationSteps.push("Consider medial branch block followed by RFA if not already done");
    optimizationSteps.push("Evaluate for other pain generators");
  } else if (input.procedureType === "medial-branch-block" && input.diagnosticBlockPositive) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("Positive prior diagnostic block (≥80% relief) — confirmatory MBB or RFA is appropriate");
    rationale.push("Two positive diagnostic blocks are required before RFA authorization by most payers");
  } else if (hasAxialPain && hasPainExtension && hasNoNeurologic && conservMonths >= 3) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Axial spine pain with extension-related pattern and no significant neurologic deficit");
    rationale.push("Clinical pattern consistent with facetogenic pain");
    rationale.push("Conservative therapy trial completed");
  } else if (conservMonths < 3) {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient");
    optimizationSteps.push("Continue PT and analgesics for ≥3 months");
  } else {
    cor = "IIb"; urgency = "Insufficient Criteria";
    rationale.push("Clinical criteria for facetogenic pain not clearly met");
    optimizationSteps.push("Document axial pain pattern, extension provocation, and absence of radicular symptoms");
  }

  if (painScore >= 7) rationale.push("Severe pain (NRS ≥7) supports intervention");
  if (input.priorFacetResponse === "good") rationale.push("Prior facet injection response was good — repeat injection appropriate");

  return { recommendation: cor === "I" ? "Facet Injection / MBB Recommended" : cor === "IIa" ? "Facet Injection Reasonable" : "Continue Conservative Therapy", cor, loe: "B", urgency, rationale, contraindications, optimizationSteps };
}
